#include "agx_win32_construction_address.h"
#include <assert.h>
int main(void){AGX_WIN32_CONSTRUCTION_SPACE s; APPLE_AGX_U64 a=0,b=0,r=0;assert(AgxWin32ConstructionInitialize(&s,0x1000000000ULL,7)==AgxWin32ConstructionSuccess);assert(AgxWin32ConstructionReserve(&s,1,11,1,&a)==AgxWin32ConstructionSuccess&&a==0x1000000000ULL);assert(AgxWin32ConstructionReserve(&s,2,12,0x4001,&b)==AgxWin32ConstructionSuccess&&b==0x1000004000ULL);assert(AgxWin32ConstructionResolve(&s,1,11,0,1,&r)==AgxWin32ConstructionSuccess&&r==a);assert(AgxWin32ConstructionResolve(&s,1,12,0,1,&r)==AgxWin32ConstructionStale);assert(AgxWin32ConstructionResolve(&s,2,12,0x4001,1,&r)==AgxWin32ConstructionRange);assert(AgxWin32ConstructionRelease(&s,1,11)==AgxWin32ConstructionSuccess);assert(AgxWin32ConstructionResolve(&s,1,11,0,1,&r)==AgxWin32ConstructionStale);return 0;}
